import importlib
import os
import sys
from collections.abc import Iterator

import pytest
from fastapi.testclient import TestClient


@pytest.fixture()
def db_path(tmp_path) -> Iterator[str]:
    path = tmp_path / "test_taskflow.db"
    yield str(path)


@pytest.fixture()
def client(db_path: str, monkeypatch: pytest.MonkeyPatch) -> Iterator[TestClient]:
    """Fresh FastAPI app bound to an isolated temp SQLite file per test.

    The app's engine is built at import time from TASKFLOW_DB_PATH, so every
    app-related module must be re-imported after the env var is set, ensuring
    tests never touch the real backend/data/taskflow.db.
    """
    monkeypatch.setenv("TASKFLOW_DB_PATH", db_path)

    for mod_name in list(sys.modules):
        if mod_name == "app" or mod_name.startswith("app."):
            del sys.modules[mod_name]

    main = importlib.import_module("app.main")

    with TestClient(main.app) as test_client:
        yield test_client

    for mod_name in list(sys.modules):
        if mod_name == "app" or mod_name.startswith("app."):
            del sys.modules[mod_name]


def reopen_client(db_path: str) -> TestClient:
    """Build a brand-new app+engine bound to the same db file — simulates a restart."""
    for mod_name in list(sys.modules):
        if mod_name == "app" or mod_name.startswith("app."):
            del sys.modules[mod_name]
    os.environ["TASKFLOW_DB_PATH"] = db_path
    main = importlib.import_module("app.main")
    return TestClient(main.app)

