import { ApiError } from "../types";
import type { Task, TaskCreateInput, TaskUpdateInput, TaskStatus } from "../types";

const BASE_URL: string = import.meta.env.VITE_API_BASE_URL ?? "/api";

interface ListTasksParams {
  q?: string;
  status?: TaskStatus;
}

async function handleResponse<T>(response: Response): Promise<T> {
  if (response.status === 204) {
    return undefined as T;
  }

  let body: unknown = null;
  try {
    body = await response.json();
  } catch {
    body = null;
  }

  if (!response.ok) {
    const detail = body && typeof body === "object" ? (body as { detail?: unknown }).detail : null;
    if (Array.isArray(detail)) {
      throw new ApiError("Request validation failed", response.status, detail as never);
    }
    const message = typeof detail === "string" ? detail : `Request failed with status ${response.status}`;
    throw new ApiError(message, response.status);
  }

  return body as T;
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let response: Response;
  try {
    response = await fetch(`${BASE_URL}${path}`, {
      ...init,
      headers: {
        "Content-Type": "application/json",
        ...(init?.headers ?? {}),
      },
    });
  } catch {
    throw new ApiError("Could not reach the server. Check your connection and try again.", 0);
  }
  return handleResponse<T>(response);
}

export function listTasks(params: ListTasksParams): Promise<Task[]> {
  const search = new URLSearchParams();
  if (params.q) search.set("q", params.q);
  if (params.status) search.set("status", params.status);
  const query = search.toString();
  return request<Task[]>(`/tasks${query ? `?${query}` : ""}`);
}

export function createTask(input: TaskCreateInput): Promise<Task> {
  return request<Task>("/tasks", { method: "POST", body: JSON.stringify(input) });
}

export function updateTask(id: string, input: TaskUpdateInput): Promise<Task> {
  return request<Task>(`/tasks/${id}`, { method: "PATCH", body: JSON.stringify(input) });
}

export function deleteTask(id: string): Promise<void> {
  return request<void>(`/tasks/${id}`, { method: "DELETE" });
}

