import { useCallback, useEffect, useState } from "react";

import { listTasks } from "../api/client";
import { ApiError } from "../types";
import type { StatusFilter, Task } from "../types";

interface UseTasksResult {
  tasks: Task[] | null;
  loading: boolean;
  error: ApiError | null;
  refetch: () => void;
}

export function useTasks(query: string, status: StatusFilter): UseTasksResult {
  const [tasks, setTasks] = useState<Task[] | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<ApiError | null>(null);
  const [version, setVersion] = useState(0);

  const refetch = useCallback(() => setVersion((v) => v + 1), []);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    listTasks({ q: query || undefined, status: status === "all" ? undefined : status })
      .then((result) => {
        if (!cancelled) {
          setTasks(result);
        }
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          setError(err instanceof ApiError ? err : new ApiError("Unexpected error", 0));
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [query, status, version]);

  return { tasks, loading, error, refetch };
}

