import { ApiError } from "../types";
import type { Task, TaskStatus } from "../types";
import { TaskItem } from "./TaskItem";

interface TaskListProps {
  tasks: Task[] | null;
  loading: boolean;
  error: ApiError | null;
  hasActiveFilters: boolean;
  onRetry: () => void;
  onEdit: (id: string, values: { title: string; description: string }) => Promise<void>;
  onStatusChange: (id: string, status: TaskStatus) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
}

export function TaskList({
  tasks,
  loading,
  error,
  hasActiveFilters,
  onRetry,
  onEdit,
  onStatusChange,
  onDelete,
}: TaskListProps) {
  if (loading) {
    return (
      <p role="status" className="task-list-status">
        Loading tasks…
      </p>
    );
  }

  if (error) {
    return (
      <div role="alert" className="task-list-status task-list-error">
        <p>Couldn&apos;t load tasks: {error.message}</p>
        <button type="button" onClick={onRetry}>
          Retry
        </button>
      </div>
    );
  }

  if (!tasks || tasks.length === 0) {
    return (
      <p role="status" className="task-list-status">
        {hasActiveFilters
          ? "No tasks match your search or filter."
          : "No tasks yet. Create your first task above."}
      </p>
    );
  }

  return (
    <ul className="task-list" aria-label="Tasks">
      {tasks.map((task) => (
        <TaskItem
          key={task.id}
          task={task}
          onEdit={onEdit}
          onStatusChange={onStatusChange}
          onDelete={onDelete}
        />
      ))}
    </ul>
  );
}

