import { useEffect, useState } from "react";

import { createTask, deleteTask, updateTask } from "./api/client";
import { SearchFilterBar } from "./components/SearchFilterBar";
import { TaskForm } from "./components/TaskForm";
import { TaskList } from "./components/TaskList";
import { useTasks } from "./hooks/useTasks";
import type { StatusFilter, TaskStatus } from "./types";

const SEARCH_DEBOUNCE_MS = 300;

export default function App() {
  const [searchInput, setSearchInput] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [status, setStatus] = useState<StatusFilter>("all");

  useEffect(() => {
    const handle = setTimeout(() => setDebouncedQuery(searchInput), SEARCH_DEBOUNCE_MS);
    return () => clearTimeout(handle);
  }, [searchInput]);

  const { tasks, loading, error, refetch } = useTasks(debouncedQuery, status);

  return (
    <main className="app">
      <h1>TaskFlow</h1>

      <section aria-labelledby="new-task-heading">
        <h2 id="new-task-heading">New task</h2>
        <TaskForm
          submitLabel="Add task"
          onSubmit={async (values) => {
            await createTask({ title: values.title, description: values.description || null });
            refetch();
          }}
        />
      </section>

      <section aria-labelledby="tasks-heading">
        <h2 id="tasks-heading">Tasks</h2>
        <SearchFilterBar
          query={searchInput}
          onQueryChange={setSearchInput}
          status={status}
          onStatusChange={setStatus}
        />
        <TaskList
          tasks={tasks}
          loading={loading}
          error={error}
          hasActiveFilters={debouncedQuery.trim().length > 0 || status !== "all"}
          onRetry={refetch}
          onEdit={async (id, values) => {
            await updateTask(id, { title: values.title, description: values.description || null });
            refetch();
          }}
          onStatusChange={async (id, next: TaskStatus) => {
            await updateTask(id, { status: next });
            refetch();
          }}
          onDelete={async (id) => {
            await deleteTask(id);
            refetch();
          }}
        />
      </section>
    </main>
  );
}

