import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";

import { ApiError } from "../types";
import { TaskForm } from "./TaskForm";

describe("TaskForm", () => {
  it("labels the title and description fields accessibly", () => {
    render(<TaskForm submitLabel="Add task" onSubmit={vi.fn()} />);
    expect(screen.getByLabelText("Title")).toBeInTheDocument();
    expect(screen.getByLabelText("Description (optional)")).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Add task" })).toBeInTheDocument();
  });

  it("rejects a whitespace-only title without calling onSubmit", async () => {
    const onSubmit = vi.fn();
    const user = userEvent.setup();
    render(<TaskForm submitLabel="Add task" onSubmit={onSubmit} />);

    await user.type(screen.getByLabelText("Title"), "   ");
    await user.click(screen.getByRole("button", { name: "Add task" }));

    expect(await screen.findByRole("alert")).toHaveTextContent("Title is required.");
    expect(onSubmit).not.toHaveBeenCalled();
  });

  it("rejects a title over 120 characters without calling onSubmit", async () => {
    const onSubmit = vi.fn();
    const user = userEvent.setup();
    render(<TaskForm submitLabel="Add task" onSubmit={onSubmit} />);

    await user.type(screen.getByLabelText("Title"), "a".repeat(121));
    await user.click(screen.getByRole("button", { name: "Add task" }));

    expect(await screen.findByRole("alert")).toHaveTextContent("at most 120 characters");
    expect(onSubmit).not.toHaveBeenCalled();
  });

  it("rejects a description over 500 characters without calling onSubmit", async () => {
    const onSubmit = vi.fn();
    const user = userEvent.setup();
    render(<TaskForm submitLabel="Add task" onSubmit={onSubmit} />);

    await user.type(screen.getByLabelText("Title"), "Valid title");
    await user.type(screen.getByLabelText("Description (optional)"), "d".repeat(501));
    await user.click(screen.getByRole("button", { name: "Add task" }));

    expect(await screen.findByRole("alert")).toHaveTextContent("at most 500 characters");
    expect(onSubmit).not.toHaveBeenCalled();
  });

  it("submits trimmed values and clears the form on success", async () => {
    const onSubmit = vi.fn().mockResolvedValue(undefined);
    const user = userEvent.setup();
    render(<TaskForm submitLabel="Add task" onSubmit={onSubmit} />);

    await user.type(screen.getByLabelText("Title"), "  Buy milk  ");
    await user.click(screen.getByRole("button", { name: "Add task" }));

    await waitFor(() => expect(onSubmit).toHaveBeenCalledWith({ title: "Buy milk", description: "" }));
    await waitFor(() => expect(screen.getByLabelText("Title")).toHaveValue(""));
  });

  it("shows a form-level error when the submission is rejected by the server", async () => {
    const onSubmit = vi.fn().mockRejectedValue(new ApiError("Title must be at most 120 characters", 422));
    const user = userEvent.setup();
    render(<TaskForm submitLabel="Add task" onSubmit={onSubmit} />);

    await user.type(screen.getByLabelText("Title"), "Valid title");
    await user.click(screen.getByRole("button", { name: "Add task" }));

    expect(await screen.findByRole("alert")).toHaveTextContent("Title must be at most 120 characters");
  });

  it("calls onCancel when the cancel button is clicked", async () => {
    const onCancel = vi.fn();
    const user = userEvent.setup();
    render(
      <TaskForm
        submitLabel="Save changes"
        initialTitle="Existing"
        onSubmit={vi.fn()}
        onCancel={onCancel}
      />,
    );

    await user.click(screen.getByRole("button", { name: "Cancel" }));
    expect(onCancel).toHaveBeenCalledTimes(1);
  });
});

