import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";

import { SearchFilterBar } from "./SearchFilterBar";

describe("SearchFilterBar", () => {
  it("labels the search input and status filter accessibly", () => {
    render(
      <SearchFilterBar query="" onQueryChange={vi.fn()} status="all" onStatusChange={vi.fn()} />,
    );
    expect(screen.getByLabelText("Search tasks")).toBeInTheDocument();
    expect(screen.getByLabelText("Filter by status")).toBeInTheDocument();
  });

  it("reports every keystroke in the search box", async () => {
    const onQueryChange = vi.fn();
    const user = userEvent.setup();
    render(
      <SearchFilterBar query="" onQueryChange={onQueryChange} status="all" onStatusChange={vi.fn()} />,
    );

    await user.type(screen.getByLabelText("Search tasks"), "milk");
    expect(onQueryChange).toHaveBeenCalledTimes(4);
    expect(onQueryChange).toHaveBeenLastCalledWith("milk");
  });

  it("lists all three statuses plus an all-statuses option", () => {
    render(
      <SearchFilterBar query="" onQueryChange={vi.fn()} status="all" onStatusChange={vi.fn()} />,
