7	interface UseTasksResult {
8	  tasks: Task[] | null;
9	  loading: boolean;
10	  error: ApiError | null;
11	  refetch: () => void;
12	}
13	
14	export function useTasks(query: string, status: StatusFilter): UseTasksResult {
15	  const [tasks, setTasks] = useState<Task[] | null>(null);
16	  const [loading, setLoading] = useState(true);
17	  const [error, setError] = useState<ApiError | null>(null);
18	  const [version, setVersion] = useState(0);
19	
20	  const refetch = useCallback(() => setVersion((v) => v + 1), []);
21	
22	  useEffect(() => {
23	    let cancelled = false;
24	    // Resetting loading/error synchronously here is the standard React
25	    // data-fetching-effect pattern (see react.dev/learn/synchronizing-with-effects);
26	    // the cascading render it triggers is bounded by the cancelled-flag cleanup below.
27	    // eslint-disable-next-line react-hooks/set-state-in-effect
28	    setLoading(true);
29	    setError(null);
30	
31	    listTasks({ q: query || undefined, status: status === "all" ? undefined : status })
32	      .then((result) => {
33	        if (!cancelled) {
34	          setTasks(result);
35	        }
36	      })
37	      .catch((err: unknown) => {
38	        if (!cancelled) {
39	          setError(err instanceof ApiError ? err : new ApiError("Unexpected error", 0));
40	        }
41	      })
42	      .finally(() => {
43	        if (!cancelled) {
44	          setLoading(false);
45	        }
46	      });
47	
48	    return () => {
49	      cancelled = true;
50	    };
51	  }, [query, status, version]);
52	
53	  return { tasks, loading, error, refetch };
54	}
