4	const BASE_URL: string = import.meta.env.VITE_API_BASE_URL ?? "/api";
5	
6	interface ListTasksParams {
7	  q?: string;
8	  status?: TaskStatus;
9	}
10	
11	async function handleResponse<T>(response: Response): Promise<T> {
12	  if (response.status === 204) {
13	    return undefined as T;
14	  }
15	
16	  let body: unknown = null;
17	  try {
18	    body = await response.json();
19	  } catch {
20	    // No JSON body (e.g. a plain 500 or a network-level failure) — treat as null.
21	  }
22	
23	  if (!response.ok) {
24	    const detail = body && typeof body === "object" ? (body as { detail?: unknown }).detail : null;
25	    if (Array.isArray(detail)) {
26	      throw new ApiError("Request validation failed", response.status, detail as never);
27	    }
28	    const message = typeof detail === "string" ? detail : `Request failed with status ${response.status}`;
29	    throw new ApiError(message, response.status);
30	  }
31	
32	  return body as T;
33	}
34	
35	async function request<T>(path: string, init?: RequestInit): Promise<T> {
36	  let response: Response;
37	  try {
38	    response = await fetch(`${BASE_URL}${path}`, {
39	      ...init,
40	      headers: {
41	        "Content-Type": "application/json",
42	        ...(init?.headers ?? {}),
43	      },
44	    });
45	  } catch {
46	    throw new ApiError("Could not reach the server. Check your connection and try again.", 0);
47	  }
48	  return handleResponse<T>(response);
49	}
