51	export function listTasks(params: ListTasksParams): Promise<Task[]> {
52	  const search = new URLSearchParams();
53	  if (params.q) search.set("q", params.q);
54	  if (params.status) search.set("status", params.status);
55	  const query = search.toString();
56	  return request<Task[]>(`/tasks${query ? `?${query}` : ""}`);
57	}
58	
59	export function createTask(input: TaskCreateInput): Promise<Task> {
60	  return request<Task>("/tasks", { method: "POST", body: JSON.stringify(input) });
61	}
62	
63	export function updateTask(id: string, input: TaskUpdateInput): Promise<Task> {
64	  return request<Task>(`/tasks/${id}`, { method: "PATCH", body: JSON.stringify(input) });
65	}
66	
67	export function deleteTask(id: string): Promise<void> {
68	  return request<void>(`/tasks/${id}`, { method: "DELETE" });
69	}
