from datetime import UTC, datetime
from enum import StrEnum

from pydantic import BaseModel, ConfigDict, field_validator


class TaskStatus(StrEnum):
    todo = "todo"
    doing = "doing"
    done = "done"


def _validate_title(value: str) -> str:
    trimmed = value.strip()
    if len(trimmed) < 1:
        raise ValueError("title must not be blank")
    if len(trimmed) > 120:
        raise ValueError("title must be at most 120 characters")
    return trimmed


def _validate_description(value: str | None) -> str | None:
    if value is None:
        return None
    if len(value) > 500:
        raise ValueError("description must be at most 500 characters")
    return value


class TaskCreate(BaseModel):
    title: str
    description: str | None = None
    status: TaskStatus = TaskStatus.todo

    @field_validator("title")
    @classmethod
    def validate_title(cls, v: str) -> str:
        return _validate_title(v)

    @field_validator("description")
    @classmethod
    def validate_description(cls, v: str | None) -> str | None:
        return _validate_description(v)


class TaskUpdate(BaseModel):
    title: str | None = None
    description: str | None = None
    status: TaskStatus | None = None

    @field_validator("title")
    @classmethod
    def validate_title(cls, v: str | None) -> str | None:
        if v is None:
            return None
        return _validate_title(v)

    @field_validator("description")
    @classmethod
    def validate_description(cls, v: str | None) -> str | None:
        return _validate_description(v)


class TaskRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: str
    title: str
    description: str | None
    status: TaskStatus
    created_at: datetime
    updated_at: datetime

    @field_validator("created_at", "updated_at", mode="before")
    @classmethod
    def ensure_utc(cls, v: datetime | str) -> datetime | str:
        # SQLite drops tzinfo on round-trip; every stored timestamp is written
        # as UTC by app.models._utcnow, so a naive value is always UTC here.
        if isinstance(v, datetime) and v.tzinfo is None:
            return v.replace(tzinfo=UTC)
        return v

