import { useId, useState } from "react";

import { STATUS_META, STATUS_ORDER } from "../statusMeta";
import { ApiError } from "../types";
import type { Task, TaskStatus } from "../types";
import { TaskForm } from "./TaskForm";

interface TaskItemProps {
  task: Task;
  onEdit: (id: string, values: { title: string; description: string }) => Promise<void>;
  onStatusChange: (id: string, status: TaskStatus) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
}

export function TaskItem({ task, onEdit, onStatusChange, onDelete }: TaskItemProps) {
  const [editing, setEditing] = useState(false);
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [statusError, setStatusError] = useState<string | null>(null);
  const statusSelectId = useId();

  const meta = STATUS_META[task.status];

  async function handleStatusChange(next: TaskStatus) {
    setStatusError(null);
    try {
      await onStatusChange(task.id, next);
    } catch (err) {
      setStatusError(err instanceof ApiError ? err.message : "Could not update status.");
    }
  }

  async function handleDelete() {
    setDeleting(true);
    try {
      await onDelete(task.id);
    } finally {
      setDeleting(false);
      setConfirmingDelete(false);
    }
  }

  if (editing) {
    return (
      <li className="task-item" data-testid={`task-${task.id}`}>
        <TaskForm
          initialTitle={task.title}
          initialDescription={task.description ?? ""}
          submitLabel="Save changes"
          onCancel={() => setEditing(false)}
          onSubmit={async (values) => {
            await onEdit(task.id, values);
            setEditing(false);
          }}
        />
      </li>
    );
  }

  return (
    <li className={`task-item ${meta.className}`} data-testid={`task-${task.id}`}>
      <div className="task-item-main">
        <span className="status-symbol" aria-hidden="true">
          {meta.symbol}
        </span>
        <div className="task-item-text">
          <p className="task-title">{task.title}</p>
          {task.description && <p className="task-description">{task.description}</p>}
        </div>
      </div>

      <div className="task-item-controls">
        <label htmlFor={statusSelectId}>Status for {task.title}</label>
        <select
          id={statusSelectId}
          value={task.status}
          onChange={(e) => handleStatusChange(e.target.value as TaskStatus)}
        >
          {STATUS_ORDER.map((s) => (
            <option key={s} value={s}>
              {STATUS_META[s].label}
            </option>
          ))}
        </select>
        {statusError && <p role="alert">{statusError}</p>}

        <button type="button" onClick={() => setEditing(true)}>
          Edit {task.title}
        </button>

        {confirmingDelete ? (
          <span className="delete-confirm">
            <button type="button" onClick={handleDelete} disabled={deleting}>
              {deleting ? "Deleting…" : `Confirm delete ${task.title}`}
            </button>
            <button type="button" onClick={() => setConfirmingDelete(false)} disabled={deleting}>
              Cancel
            </button>
          </span>
        ) : (
          <button type="button" onClick={() => setConfirmingDelete(true)}>
            Delete {task.title}
          </button>
        )}
      </div>
    </li>
  );
}

