import { render, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import * as client from "./api/client";
import App from "./App";
import { ApiError } from "./types";
import type { Task } from "./types";

vi.mock("./api/client");

const mockedClient = vi.mocked(client);

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: "task-1",
    title: "Buy milk",
    description: "2% please",
    status: "todo",
    created_at: "2026-07-30T00:00:00Z",
    updated_at: "2026-07-30T00:00:00Z",
    ...overrides,
  };
}

beforeEach(() => {
  mockedClient.listTasks.mockResolvedValue([]);
  mockedClient.createTask.mockResolvedValue(makeTask());
  mockedClient.updateTask.mockResolvedValue(makeTask({ status: "doing" }));
  mockedClient.deleteTask.mockResolvedValue(undefined);
});

afterEach(() => {
  vi.clearAllMocks();
});

describe("App", () => {
  it("shows a loading state before the first fetch resolves, then the empty state", async () => {
    render(<App />);
    expect(screen.getByRole("status")).toHaveTextContent("Loading tasks");
    expect(await screen.findByText("No tasks yet. Create your first task above.")).toBeInTheDocument();
  });

  it("renders tasks returned by the API", async () => {
    mockedClient.listTasks.mockResolvedValue([makeTask()]);
    render(<App />);
    expect(await screen.findByText("Buy milk")).toBeInTheDocument();
    expect(screen.getByText("2% please")).toBeInTheDocument();
  });

  it("shows a request-failure state when the initial load fails", async () => {
    mockedClient.listTasks.mockRejectedValue(new ApiError("Could not reach the server.", 0));
    render(<App />);
    expect(await screen.findByRole("alert")).toHaveTextContent("Could not reach the server.");
  });

  it("creates a task and refreshes the list", async () => {
    mockedClient.listTasks.mockResolvedValueOnce([]).mockResolvedValueOnce([makeTask()]);
    const user = userEvent.setup();
    render(<App />);

    await screen.findByText("No tasks yet. Create your first task above.");
    await user.type(screen.getByLabelText("Title"), "Buy milk");
    await user.click(screen.getByRole("button", { name: "Add task" }));

    await waitFor(() =>
      expect(mockedClient.createTask).toHaveBeenCalledWith({ title: "Buy milk", description: null }),
    );
    expect(await screen.findByText("Buy milk")).toBeInTheDocument();
  });

  it("moves a task to a new status via its status select", async () => {
    mockedClient.listTasks.mockResolvedValue([makeTask()]);
    const user = userEvent.setup();
    render(<App />);

    await screen.findByText("Buy milk");
    await user.selectOptions(screen.getByLabelText("Status for Buy milk"), "doing");

    await waitFor(() =>
      expect(mockedClient.updateTask).toHaveBeenCalledWith("task-1", { status: "doing" }),
    );
  });

  it("edits a task's title and description", async () => {
    mockedClient.listTasks.mockResolvedValue([makeTask()]);
    const user = userEvent.setup();
    render(<App />);

    await screen.findByText("Buy milk");
    await user.click(screen.getByRole("button", { name: "Edit Buy milk" }));

    const editForm = screen.getByRole("form", { name: "Save changes" });
    const titleInput = within(editForm).getByLabelText("Title");
    await user.clear(titleInput);
    await user.type(titleInput, "Buy oat milk");
    await user.click(within(editForm).getByRole("button", { name: "Save changes" }));

    await waitFor(() =>
      expect(mockedClient.updateTask).toHaveBeenCalledWith("task-1", {
        title: "Buy oat milk",
        description: "2% please",
      }),
    );
  });

  it("deletes a task after a two-step confirmation", async () => {
    mockedClient.listTasks.mockResolvedValueOnce([makeTask()]).mockResolvedValueOnce([]);
    const user = userEvent.setup();
    render(<App />);

    await screen.findByText("Buy milk");
    await user.click(screen.getByRole("button", { name: "Delete Buy milk" }));
    await user.click(screen.getByRole("button", { name: "Confirm delete Buy milk" }));

    await waitFor(() => expect(mockedClient.deleteTask).toHaveBeenCalledWith("task-1"));
    expect(await screen.findByText("No tasks yet. Create your first task above.")).toBeInTheDocument();
  });

  it("filters by status through the search/filter bar", async () => {
    mockedClient.listTasks.mockResolvedValue([]);
    const user = userEvent.setup();
    render(<App />);

    await screen.findByText("No tasks yet. Create your first task above.");
    await user.selectOptions(screen.getByLabelText("Filter by status"), "doing");

    await waitFor(() =>
      expect(mockedClient.listTasks).toHaveBeenLastCalledWith({ q: undefined, status: "doing" }),
    );
  });

  it("debounces search input before calling the API", async () => {
    mockedClient.listTasks.mockResolvedValue([]);
    const user = userEvent.setup();
    render(<App />);

    await screen.findByText("No tasks yet. Create your first task above.");
    const callsBeforeTyping = mockedClient.listTasks.mock.calls.length;
    await user.type(screen.getByLabelText("Search tasks"), "milk");

    await waitFor(
      () =>
        expect(mockedClient.listTasks).toHaveBeenLastCalledWith({ q: "milk", status: undefined }),
      { timeout: 2000 },
    );
    expect(mockedClient.listTasks.mock.calls.length).toBeLessThan(callsBeforeTyping + 4);
  });
});

