import { expect, test } from "@playwright/test";

test("create, search, filter, move through statuses, then delete a task", async ({ page }) => {
  const uniqueTitle = `E2E grocery run ${Date.now()}`;
  const taskByTitle = () => page.getByTestId(/^task-/).filter({ hasText: uniqueTitle });

  await page.goto("/");

  // Create
  await page.getByLabel("Title").fill(uniqueTitle);
  await page.getByLabel("Description (optional)").fill("Oat milk and bread");
  await page.getByRole("button", { name: "Add task" }).click();
  await expect(taskByTitle()).toBeVisible();

  // Search
  await page.getByLabel("Search tasks").fill(uniqueTitle);
  await expect(taskByTitle()).toBeVisible();
  await expect(page.getByText("No tasks match your search or filter.")).toHaveCount(0);

  await page.getByLabel("Search tasks").fill("this-will-not-match-anything");
  await expect(page.getByText("No tasks match your search or filter.")).toBeVisible();
  await page.getByLabel("Search tasks").fill("");

  // Filter — the fresh task defaults to todo
  await page.getByLabel("Filter by status").selectOption("todo");
  await expect(taskByTitle()).toBeVisible();

  await page.getByLabel("Filter by status").selectOption("done");
  await expect(taskByTitle()).toHaveCount(0);

  await page.getByLabel("Filter by status").selectOption("all");
  await expect(taskByTitle()).toBeVisible();

  // Move todo -> doing -> done
  const statusSelect = page.getByLabel(`Status for ${uniqueTitle}`);
  await statusSelect.selectOption("doing");
  await expect(statusSelect).toHaveValue("doing");

  await statusSelect.selectOption("done");
  await expect(statusSelect).toHaveValue("done");

  // Filtering by done now finds it
  await page.getByLabel("Filter by status").selectOption("done");
  await expect(taskByTitle()).toBeVisible();
  await page.getByLabel("Filter by status").selectOption("all");

  // Delete (two-step confirm)
  await page.getByRole("button", { name: `Delete ${uniqueTitle}` }).click();
  await page.getByRole("button", { name: `Confirm delete ${uniqueTitle}` }).click();

  await expect(taskByTitle()).toHaveCount(0);
});

