from sqlalchemy import func, or_, select
from sqlalchemy.orm import Session

from app.models import Task
from app.schemas import TaskCreate, TaskUpdate

_LIKE_ESCAPE_CHAR = "\\"


def _escape_like_term(term: str) -> str:
    # Escape the LIKE wildcards themselves so a literal "%" or "_" in a
    # search term is matched literally instead of matching anything/one-char.
    escaped = term.replace(_LIKE_ESCAPE_CHAR, _LIKE_ESCAPE_CHAR * 2)
    escaped = escaped.replace("%", f"{_LIKE_ESCAPE_CHAR}%")
    return escaped.replace("_", f"{_LIKE_ESCAPE_CHAR}_")


def list_tasks(db: Session, search: str | None = None, status: str | None = None) -> list[Task]:
    stmt = select(Task)
    if search:
        pattern = f"%{_escape_like_term(search.lower())}%"
        stmt = stmt.where(
            or_(
                func.lower(Task.title).like(pattern, escape=_LIKE_ESCAPE_CHAR),
                func.lower(func.coalesce(Task.description, "")).like(
                    pattern, escape=_LIKE_ESCAPE_CHAR
                ),
            )
        )
    if status:
        stmt = stmt.where(Task.status == status)
    stmt = stmt.order_by(Task.created_at.desc())
    return list(db.execute(stmt).scalars().all())


def get_task(db: Session, task_id: str) -> Task | None:
    return db.get(Task, task_id)


def create_task(db: Session, payload: TaskCreate) -> Task:
    task = Task(
        title=payload.title,
        description=payload.description,
        status=payload.status.value,
    )
    db.add(task)
    db.commit()
    db.refresh(task)
    return task


def update_task(db: Session, task_id: str, payload: TaskUpdate) -> Task | None:
    task = get_task(db, task_id)
    if task is None:
        return None
    updates = payload.model_dump(exclude_unset=True)
    for field, value in updates.items():
        if field == "status" and value is not None:
            value = value.value if hasattr(value, "value") else value
        setattr(task, field, value)
    db.add(task)
    db.commit()
    db.refresh(task)
    return task


def delete_task(db: Session, task_id: str) -> bool:
    task = get_task(db, task_id)
    if task is None:
        return False
    db.delete(task)
    db.commit()
    return True

